package main

import (
	"strings"
	"testing"
)

// oldLayoutConfig is what install wrote before host metrics went to the OTLP ingest: every
// metric receiver in one pipeline to the zharp exporter, and --no-otlp, so no otlphttp exporter.
const oldLayoutConfig = `## Zharp Collector config — generated by zharp-collector install
## OTLP receiver left out (--no-otlp); ` + "`zharp-collector update`" + ` keeps it out.

extensions:
  health_check:
    endpoint: 0.0.0.0:13133

receivers:
  hostmetrics:
    collection_interval: 5s
    scrapers:
      cpu:
      memory:
      disk:
      network:
      load:

  docker_stats:
    endpoint: unix:///var/run/docker.sock
    collection_interval: 30s
    timeout: 20s

  redis:
    endpoint: localhost:6379
    collection_interval: 30s

processors:
  batch:
    send_batch_size: 500
    timeout: 5s
  memory_limiter:
    limit_mib: 128
    spike_limit_mib: 32
    check_interval: 5s
  resourcedetection:
    detectors: [system, env]
    timeout: 5s

exporters:
  zharp:
    api_key: "${env:ZHARP_API_KEY}"
    endpoint: "http://localhost:3000/api/v1"
    inventory_file: "/var/lib/zharp-collector/inventory.json"

service:
  extensions: [health_check]
  pipelines:
    metrics:
      receivers: [hostmetrics, docker_stats, redis]
      processors: [memory_limiter, resourcedetection, batch]
      exporters: [zharp]
`

func TestUpdateMovesHostMetricsToOTLP(t *testing.T) {
	fakeHost(t)
	res, err := mergeSources(oldLayoutConfig, nil, nil, true)
	if err != nil {
		t.Fatal(err)
	}
	after := res.config
	for _, want := range []string{
		"\n  otlp_http/zharp:\n    endpoint: \"http://localhost:3000/api/v1/otlp\"\n",
		"\n  resourcedetection/host:\n    detectors: [env, system, ec2, gcp, azure]\n",
		"\n" + hostmetricsBlock,
		"\n  docker_state:\n    endpoint: unix:///var/run/docker.sock\n    collection_interval: 30s\n",
		"    metrics/host:\n      receivers: [hostmetrics, docker_stats, docker_state]\n      processors: [memory_limiter, resourcedetection/host, batch]\n      exporters: [otlp_http/zharp, zharp]\n",
		"    metrics:\n      receivers: [redis]\n      processors: [memory_limiter, resourcedetection, batch]\n      exporters: [zharp]\n",
	} {
		if !strings.Contains(after, want) {
			t.Errorf("missing %q in\n%s", want, after)
		}
	}
	// --no-otlp still keeps the receiver out; only the exporter is needed for metrics.
	if strings.Contains(after, "\n  otlp:\n") || strings.Contains(after, "traces/otlp") {
		t.Errorf("--no-otlp config gained the OTLP receiver:\n%s", after)
	}
	if strings.Contains(after, "      disk:\n") || strings.Contains(after, "collection_interval: 5s") {
		t.Errorf("old hostmetrics block left behind:\n%s", after)
	}
	if len(res.migrated) == 0 {
		t.Error("the summary should say what changed")
	}
	validateMerged(t, after)

	again, err := mergeSources(after, res.inventory, nil, true)
	if err != nil {
		t.Fatal(err)
	}
	if again.config != after || len(again.migrated) != 0 {
		t.Errorf("second run changed something: %v\n%s", again.migrated, again.config)
	}
}

func TestUpdateDropsAnEmptyMetricsPipeline(t *testing.T) {
	content := strings.Replace(oldLayoutConfig, "receivers: [hostmetrics, docker_stats, redis]", "receivers: [hostmetrics]", 1)
	after, _ := withHostMetricsPipeline(content)
	if strings.Contains(after, "\n    metrics:\n") {
		t.Errorf("empty metrics pipeline kept:\n%s", after)
	}
	if !strings.Contains(after, "    metrics/host:\n      receivers: [hostmetrics, docker_state]\n") {
		t.Errorf("host pipeline:\n%s", after[strings.Index(after, "pipelines:"):])
	}
}

func TestAddDatabaseCreatesTheMetricsPipeline(t *testing.T) {
	content := buildConfig(configSpec{metricsReceivers: []string{"hostmetrics"}})
	if strings.Contains(content, "\n    metrics:\n") {
		t.Fatal("no database, yet a metrics pipeline")
	}
	content, err := addReceiverToContent(content, "redis", "\n  redis:\n    endpoint: localhost:6379\n")
	if err != nil {
		t.Fatal(err)
	}
	content, err = addReceiverToContent(content, dockerReceiverIDs, dockerReceiverBlocks())
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"    metrics:\n      receivers: [redis]\n",
		"    metrics/host:\n      receivers: [hostmetrics, docker_stats, docker_state]\n",
	} {
		if !strings.Contains(content, want) {
			t.Errorf("missing %q in\n%s", want, content)
		}
	}
	validateMerged(t, content)
}
